const activities = ["Draw", "Read", "Run"];
function selectActivities(items, letter) {
  return items.filter(item => item.startsWith(letter));
}
function App() {
  const [letter, setLetter] = React.useState("R");
  const [dark, setDark] = React.useState(false);
  const visible = React.useMemo(() => selectActivities(activities, letter), [letter]);
  return <main data-dark={dark}>
    <p>{visible.join(", ") || "None"}</p>
    <button onClick={() => setLetter("D")}>Choose D</button>
    <button onClick={() => setDark(d => !d)}>Toggle background</button>
  </main>;
}

